/**
 * CFOP solver: Cross, F2L, OLL, PLL.
 *
 * The cross and the last layer reuse the beginner-method machinery, which
 * already speaks the reduced-state search. The new part is F2L: each of the
 * four pairs (a bottom corner plus the middle edge above it) is solved as one
 * stage of two heterogeneous pieces. Its move vocabulary is generated by
 * enumerating short sequences and keeping only those that leave the cross and
 * the already-finished slots untouched, so no stage can undo an earlier one.
 *
 * The pool is built the first time CFOP is requested and then cached, keeping
 * it off the initial page load.
 */

import {
  applyMoves,
  createSolvedCube,
  parseMoves,
  type CubeState,
  type Move,
  type Vec3,
} from "./cube";
import {
  CORNERS,
  EDGES,
  alg,
  makeStageSolver,
  piecesSolved,
  solvedEntry,
  type PieceSpec,
  type StageConfig,
  type StageSolver,
} from "./stages";
import {
  OLL_CORNERS,
  WHITE_CROSS,
  D_EDGES,
  cancelRedundant,
  solveCross,
  type SolveStage,
} from "./beginner";

const U_NORMAL: Vec3 = [0, 1, 0];

function hasUNormal(normal: Vec3): boolean {
  return normal[1] === U_NORMAL[1];
}

const U_CORNER_HOMES: readonly Vec3[] = CORNERS.slots
  .filter((slot) => slot.normals.some(hasUNormal))
  .map((slot) => slot.home);
const U_EDGE_HOMES: readonly Vec3[] = EDGES.slots
  .filter((slot) => slot.normals.some(hasUNormal))
  .map((slot) => slot.home);

/** The four F2L columns: bottom corner and the middle edge directly above it. */
const F2L_SLOTS: readonly { corner: Vec3; edge: Vec3 }[] = [
  { corner: [1, -1, 1], edge: [1, 0, 1] },
  { corner: [-1, -1, 1], edge: [-1, 0, 1] },
  { corner: [1, -1, -1], edge: [1, 0, -1] },
  { corner: [-1, -1, -1], edge: [-1, 0, -1] },
];

/**
 * Faces a pair insertion actually uses. D is excluded because it would break
 * the cross; every turn keeps the bottom layer reachable through its sides.
 */
const ALPHABET = ["U", "U'", "R", "R'", "F", "F'", "L", "L'", "B", "B'"];

function enumerateSequences(maxLength: number): Move[][] {
  const sequences: Move[][] = [];
  let frontier: Move[][] = [[]];
  for (let length = 1; length <= maxLength; length += 1) {
    const next: Move[][] = [];
    for (const prefix of frontier) {
      for (const token of ALPHABET) {
        next.push([...prefix, ...parseMoves(token)]);
      }
    }
    sequences.push(...next);
    frontier = next;
  }
  return sequences;
}

function slotSolved(state: CubeState, index: number): boolean {
  const { corner, edge } = F2L_SLOTS[index];
  return (
    piecesSolved(CORNERS, state, [corner]) &&
    piecesSolved(EDGES, state, [edge])
  );
}

/**
 * Per-stage generator pools. Pool `i` keeps the cross and slots `0..i-1`
 * solved, so a solved pair is never disturbed.
 */
function buildPools(): readonly (readonly Move[][])[] {
  const solved = createSolvedCube();
  const sequences = enumerateSequences(4);
  const pools: Move[][][] = F2L_SLOTS.map(() => []);
  for (const sequence of sequences) {
    const state = applyMoves(solved, sequence);
    if (!piecesSolved(EDGES, state, D_EDGES)) continue;
    for (let stage = 0; stage < F2L_SLOTS.length; stage += 1) {
      let preserved = true;
      for (let earlier = 0; earlier < stage; earlier += 1) {
        if (!slotSolved(state, earlier)) {
          preserved = false;
          break;
        }
      }
      if (preserved) pools[stage].push(sequence);
    }
  }
  return pools;
}

function f2lConfig(index: number, generators: readonly Move[][]): StageConfig {
  const { corner, edge } = F2L_SLOTS[index];
  const pieces: PieceSpec[] = [
    { kind: CORNERS, home: corner },
    { kind: EDGES, home: edge },
  ];
  return {
    name: `f2l-${index + 1}`,
    pieces,
    goalOptions: [
      [solvedEntry(CORNERS, corner)],
      [solvedEntry(EDGES, edge)],
    ],
    generators,
  };
}

let f2lSolvers: readonly StageSolver[] | null = null;

function f2lSolver(index: number): StageSolver {
  if (!f2lSolvers) {
    const pools = buildPools();
    f2lSolvers = pools.map((generators, slot) =>
      makeStageSolver(f2lConfig(slot, generators)),
    );
  }
  return f2lSolvers[index];
}

/* ------------------------------------------------------------------ *
 * Last layer. Orientation reuses the beginner stages; permutation uses
 * proper PLL algorithms so a pair of them is normally enough.
 * ------------------------------------------------------------------ */

const U_MOVES: Move[][] = [alg("U"), alg("U'"), alg("U U")];

/**
 * Wrap an edge-only algorithm in every `U` rotation. A bare `U` would rotate
 * the already-solved corners, so PLL edges must stay inside a conjugate.
 */
function conjugates(notation: string): Move[][] {
  return [
    alg(notation),
    alg(`U ${notation} U'`),
    alg(`U U ${notation} U U`),
    alg(`U' ${notation} U`),
  ];
}

const CPLL_STAGE: StageConfig = {
  name: "cpll",
  pieces: U_CORNER_HOMES.map((home): PieceSpec => ({ kind: CORNERS, home })),
  goalOptions: U_CORNER_HOMES.map((home) => [solvedEntry(CORNERS, home)]),
  generators: [
    ...U_MOVES,
    // Aa and Ab are corner 3-cycles; T also swaps an edge pair, which lets the
    // search reach the odd corner permutations a 3-cycle alone cannot.
    alg("R' F R' B B R F' R' B B R R"),
    alg("R R B B R F R' B B R F' R"),
    alg("R U R' U' R' F R R U' R' U' R U R' F'"),
  ],
};

const EPLL_STAGE: StageConfig = {
  name: "epll",
  pieces: U_EDGE_HOMES.map((home): PieceSpec => ({ kind: EDGES, home })),
  goalOptions: U_EDGE_HOMES.map((home) => [solvedEntry(EDGES, home)]),
  generators: [
    // Ua and Ub are edge 3-cycles, H a double swap; together they cover every
    // even edge permutation left once the corners are home.
    ...conjugates("R U' R U R U R U' R' U' R R"),
    ...conjugates("R R U R U R' U' R' U' R' U R'"),
    ...conjugates("R R U U R U U R R U U R R U U R U U R R"),
  ],
};

const PLL_CORNERS = makeStageSolver(CPLL_STAGE);
const PLL_EDGES = makeStageSolver(EPLL_STAGE);

interface CfopStage {
  readonly id: string;
  readonly title: string;
  readonly detail: string;
  readonly solve: (state: CubeState) => Move[];
}

function stageDefinitions(): readonly CfopStage[] {
  const f2l: CfopStage[] = F2L_SLOTS.map((_, index) => ({
    id: `f2l-${index + 1}`,
    title: `F2L pasangan ${index + 1}`,
    detail: `Satukan sudut dan tepi pasangan ${index + 1} lalu masukkan ke lapisan tengah.`,
    solve: f2lSolver(index),
  }));
  return [
    {
      id: "cross",
      title: "Cross",
      detail: "Susun cross kuning di sisi bawah, langsung dengan warna sisinya.",
      solve: solveCross,
    },
    ...f2l,
    {
      id: "eoll",
      title: "OLL tepi (cross putih)",
      detail: "Balik tepi atas sampai membentuk palang putih.",
      solve: WHITE_CROSS,
    },
    {
      id: "ocll",
      title: "OLL sudut",
      detail: "Putar sudut atas sampai seluruh sisi atas putih.",
      solve: OLL_CORNERS,
    },
    {
      id: "cpll",
      title: "PLL sudut",
      detail: "Pindahkan sudut atas ke posisi akhirnya.",
      solve: PLL_CORNERS,
    },
    {
      id: "epll",
      title: "PLL tepi",
      detail: "Putar tepi atas sampai kubus selesai.",
      solve: PLL_EDGES,
    },
  ];
}

/** Full staged CFOP solution for the current cube state. */
export function solveCfop(state: CubeState): SolveStage[] {
  let current = state;
  const result: SolveStage[] = [];
  for (const stage of stageDefinitions()) {
    const moves = cancelRedundant(stage.solve(current));
    current = applyMoves(current, moves);
    result.push({
      id: stage.id,
      title: stage.title,
      detail: stage.detail,
      moves,
    });
  }
  return result;
}
